/// Answers one generated read from the hook's `&self` host (`None`
/// means the read is not this generator's, and the caller keeps its own
/// `no such read` error).
/// The arms are closures (so `?` widens to the match's `Some`);
#[allow(clippy::redundant_closure_call)]
#[allow(unused_variables)]
pub(crate) fn synthetic_read(
    lua: &Lua,
    h: &dyn SyntheticHost,
    what: &str,
    rest: MultiValue,
) -> Option<mlua::Result<Value>> {
    match what {
        "synthetic_mixed_read" => Some((|h: &dyn SyntheticHost| -> mlua::Result<Value> {
            match h.synthetic_mixed_read() {
                Some(v) => Ok({
                    let t = lua.create_table()?;
                    t.set(1, v.0)?;
                    t.set(2, v.1)?;
                    Value::Table(t)
                }),
                None => Ok(Value::Nil),
            }
        })(h)),
        "synthetic_vec_read" => Some((|h: &dyn SyntheticHost| -> mlua::Result<Value> {
            match h.synthetic_vec_read() {
                Some(v) => Ok({
                    let t = lua.create_table()?;
                    t.set(1, crate::lua_mods::goals::vec3(lua, v.0)?)?;
                    t.set(2, crate::generated_runtime::pos_table(lua, v.1)?)?;
                    Value::Table(t)
                }),
                None => Ok(Value::Nil),
            }
        })(h)),
        "synthetic_uuid_read" => Some((|h: &dyn SyntheticHost| -> mlua::Result<Value> {
            match h.synthetic_uuid_read() {
                Some(v) => Ok(Value::String(
                    lua.create_string(crate::generated_runtime::uuid_text(v))?,
                )),
                None => Ok(Value::Nil),
            }
        })(h)),
        _ => None,
    }
}

/// The synthetic conformance host: one method per synthetic
/// row, so every emitter branch the enabled helpers alone
/// never reach is compiled and executed in the normal build.
pub(crate) trait SyntheticHost {
    fn synthetic_direction_probe(&mut self, face: Direction) -> bool;
    fn synthetic_float_pair(&mut self, pair: Option<(f32, f64)>) -> bool;
    fn synthetic_int_pair(&mut self, pair: Option<(i32, i32)>) -> bool;
    fn synthetic_vec_pair(&mut self, pair: Option<([f64; 3], [i32; 3])>) -> bool;
    fn synthetic_text_pair(&mut self, pair: Option<(&str, Option<&str>)>) -> bool;
    fn synthetic_unit_action(&mut self);
    fn synthetic_state_probe(&mut self, state: Option<BlockStateId>) -> bool;
    fn synthetic_mixed_read(&self) -> Option<(bool, f64)>;
    fn synthetic_vec_read(&self) -> Option<([f64; 3], [i32; 3])>;
    fn synthetic_uuid_read(&self) -> Option<u128>;
    fn state_named(&self, name: &str) -> Option<BlockStateId>;
}

struct SyntheticDouble {
    lines: Mutex<Vec<String>>,
    none: bool,
    refuse: bool,
}

impl SyntheticDouble {
    fn record(&self, name: &str, args: &[String]) {
        let line = if args.is_empty() {
            name.to_owned()
        } else {
            format!("{} {}", name, args.join(" "))
        };
        self.lines.lock().unwrap().push(line);
    }
    fn logged(&self) -> Vec<String> {
        self.lines.lock().unwrap().clone()
    }
}

impl SyntheticHost for SyntheticDouble {
    fn synthetic_direction_probe(&mut self, face: Direction) -> bool {
        self.record("synthetic_direction_probe", &[format!("{:?}", face)]);
        !self.refuse
    }
    fn synthetic_float_pair(&mut self, pair: Option<(f32, f64)>) -> bool {
        self.record("synthetic_float_pair", &[format!("{:?}", pair)]);
        !self.refuse
    }
    fn synthetic_int_pair(&mut self, pair: Option<(i32, i32)>) -> bool {
        self.record("synthetic_int_pair", &[format!("{:?}", pair)]);
        !self.refuse
    }
    fn synthetic_vec_pair(&mut self, pair: Option<([f64; 3], [i32; 3])>) -> bool {
        self.record("synthetic_vec_pair", &[format!("{:?}", pair)]);
        !self.refuse
    }
    fn synthetic_text_pair(&mut self, pair: Option<(&str, Option<&str>)>) -> bool {
        self.record("synthetic_text_pair", &[format!("{:?}", pair)]);
        !self.refuse
    }
    fn synthetic_unit_action(&mut self) {
        self.record("synthetic_unit_action", &[]);
    }
    fn synthetic_state_probe(&mut self, state: Option<BlockStateId>) -> bool {
        self.record("synthetic_state_probe", &[format!("{:?}", state)]);
        !self.refuse
    }
    fn synthetic_mixed_read(&self) -> Option<(bool, f64)> {
        self.record("synthetic_mixed_read", &[]);
        if self.none { None } else { Some((true, 2.5)) }
    }
    fn synthetic_vec_read(&self) -> Option<([f64; 3], [i32; 3])> {
        self.record("synthetic_vec_read", &[]);
        if self.none {
            None
        } else {
            Some(([1.5, 2.5, 3.5], [3, 4, 5]))
        }
    }
    fn synthetic_uuid_read(&self) -> Option<u128> {
        self.record("synthetic_uuid_read", &[]);
        if self.none { None } else { Some(STEVE_UUID) }
    }
    fn state_named(&self, name: &str) -> Option<BlockStateId> {
        (name == "ruby:gen").then_some(BlockStateId(7))
    }
}
// Generated by `cargo run -p xtask -- lua-helpers`: do not edit.
// One test per emitted helper, over the `GenHost` recording double: the
// arguments reach the host exactly, a read returns its exact canned
// value (and nil for None), an unresolvable player or
// entity is a silent no-op/nil without calling the host, a malformed
// script argument is an error naming it, and the names raise in a client
// state and a draw hook. The drain test drives the real queue through a
// hook dispatch.

use std::sync::Mutex;

const STEVE_UUID: u128 = 0x123e4567_e89b_12d3_a456_426614174000;

fn args(lua: &Lua, values: &[mlua::Value]) -> Table {
    let t = lua.create_table().unwrap();
    for (i, v) in values.iter().enumerate() {
        t.set(i + 1, v.clone()).unwrap();
    }
    t
}

fn rest(_lua: &Lua, values: &[mlua::Value]) -> mlua::MultiValue {
    values.iter().cloned().collect()
}

fn lua() -> Lua {
    Lua::new()
}

fn synthetic_host(none: bool, refuse: bool) -> SyntheticDouble {
    SyntheticDouble {
        lines: Mutex::new(Vec::new()),
        none,
        refuse,
    }
}

#[test]
fn synthetic_direction_probe_is_generated_and_exact() {
    let lua = lua();
    let mut host = synthetic_host(false, false);
    let t = args(
        &lua,
        &[mlua::Value::String(lua.create_string("north").unwrap())],
    );
    run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
        .unwrap()
        .unwrap();
    assert_eq!(host.logged(), ["synthetic_direction_probe North"]);
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("down").unwrap())],
        );
        run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("Down"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("up").unwrap())],
        );
        run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("Up"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("north").unwrap())],
        );
        run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("North"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("south").unwrap())],
        );
        run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("South"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("west").unwrap())],
        );
        run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("West"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("east").unwrap())],
        );
        run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("East"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(lua.create_string("upwards").unwrap())],
        );
        let err = run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_direction_probe.face"), "{text}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Integer(3)]);
        let err = run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_direction_probe.face"), "{text}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Table(lua.create_table().unwrap())]);
        let err = run_synthetic_action(&lua, &mut host, "synthetic_direction_probe", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_direction_probe"), "{text}");
        assert!(text.contains("face"), "{text}");
    }
}

