fn synthetic_float_pair_is_generated_and_exact() {
    let lua = lua();
    let mut host = synthetic_host(false, false);
    let t = args(
        &lua,
        &[{
            let t = lua.create_table().unwrap();
            t.set(1, 1.5).unwrap();
            t.set(2, 2.5).unwrap();
            mlua::Value::Table(t)
        }],
    );
    run_synthetic_action(&lua, &mut host, "synthetic_float_pair", &t)
        .unwrap()
        .unwrap();
    assert_eq!(host.logged(), ["synthetic_float_pair Some((1.5, 2.5))"]);
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Table(lua.create_table().unwrap())]);
        let err = run_synthetic_action(&lua, &mut host, "synthetic_float_pair", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_float_pair.pair"), "{text}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Table(lua.create_table().unwrap())]);
        let err = run_synthetic_action(&lua, &mut host, "synthetic_float_pair", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_float_pair"), "{text}");
        assert!(text.contains("pair"), "{text}");
    }
}

