#[test]
fn synthetic_state_probe_is_generated_and_exact() {
    let lua = lua();
    let mut host = synthetic_host(false, false);
    let t = args(
        &lua,
        &[mlua::Value::String(lua.create_string("ruby:gen").unwrap())],
    );
    run_synthetic_action(&lua, &mut host, "synthetic_state_probe", &t)
        .unwrap()
        .unwrap();
    assert_eq!(
        host.logged(),
        ["synthetic_state_probe Some(BlockStateId(7))"]
    );
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Nil]);
        run_synthetic_action(&lua, &mut host, "synthetic_state_probe", &t)
            .unwrap()
            .unwrap();
        let last = host.logged().last().cloned().unwrap_or_default();
        assert!(last.contains("None"), "{last}");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(
            &lua,
            &[mlua::Value::String(
                lua.create_string("ruby:gibberish").unwrap(),
            )],
        );
        let err = run_synthetic_action(&lua, &mut host, "synthetic_state_probe", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_state_probe.state"), "{text}");
        assert!(host.logged().is_empty(), "a bad argument calls nothing");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Integer(3)]);
        let err = run_synthetic_action(&lua, &mut host, "synthetic_state_probe", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_state_probe.state"), "{text}");
        assert!(host.logged().is_empty(), "a bad argument calls nothing");
    }
    {
        let mut host = synthetic_host(false, false);
        let t = args(&lua, &[mlua::Value::Table(lua.create_table().unwrap())]);
        let err = run_synthetic_action(&lua, &mut host, "synthetic_state_probe", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("synthetic_state_probe"), "{text}");
        assert!(text.contains("state"), "{text}");
    }
}

#[test]
fn synthetic_mixed_read_is_generated_and_exact() {
    let lua = lua();
    let h = synthetic_host(false, false);
    let v = synthetic_read(&lua, &h, "synthetic_mixed_read", rest(&lua, &[]))
        .unwrap()
        .unwrap();
    assert!(matches!(v, mlua::Value::Table(_)), "{v:?}");
    if let mlua::Value::Table(t) = &v {
        assert!(t.get::<bool>(1).unwrap());
        assert_eq!(t.get::<f64>(2).unwrap(), 2.5);
    }
    assert_eq!(h.logged(), ["synthetic_mixed_read"]);
    {
        let h = synthetic_host(true, false);
        let v = synthetic_read(&lua, &h, "synthetic_mixed_read", rest(&lua, &[]))
            .unwrap()
            .unwrap();
        assert!(matches!(v, mlua::Value::Nil), "{v:?}");
    }
}

#[test]
fn synthetic_vec_read_is_generated_and_exact() {
    let lua = lua();
    let h = synthetic_host(false, false);
    let v = synthetic_read(&lua, &h, "synthetic_vec_read", rest(&lua, &[]))
        .unwrap()
        .unwrap();
    assert!(matches!(v, mlua::Value::Table(_)), "{v:?}");
    if let mlua::Value::Table(t) = &v {
        assert_eq!(
            t.get::<mlua::Table>(1).unwrap().get::<f64>("x").unwrap(),
            1.5
        );
        assert_eq!(
            t.get::<mlua::Table>(1).unwrap().get::<f64>("y").unwrap(),
            2.5
        );
        assert_eq!(
            t.get::<mlua::Table>(1).unwrap().get::<f64>("z").unwrap(),
            3.5
        );
        assert_eq!(t.get::<mlua::Table>(2).unwrap().get::<i64>("x").unwrap(), 3);
        assert_eq!(t.get::<mlua::Table>(2).unwrap().get::<i64>("y").unwrap(), 4);
        assert_eq!(t.get::<mlua::Table>(2).unwrap().get::<i64>("z").unwrap(), 5);
    }
    assert_eq!(h.logged(), ["synthetic_vec_read"]);
    {
        let h = synthetic_host(true, false);
        let v = synthetic_read(&lua, &h, "synthetic_vec_read", rest(&lua, &[]))
            .unwrap()
            .unwrap();
        assert!(matches!(v, mlua::Value::Nil), "{v:?}");
    }
}

